{
  "name": "NI计数器输出模块",
  "name_en": "NI Counter Output Module",
  "manufacturer": "National Instruments",
  "description": "这是一类带有计数器/定时器输出通道的NI数据采集设备，可按设定的初始延时、高电平时间、低电平时间或周期输出定时脉冲信号。实验中常用于产生TTL触发、同步脉冲、门控信号或时序控制信号，以协调激光、相机、探测器和其他仪器的工作。",
  "description_en": "This is an NI data acquisition device with counter/timer output channels that can generate timed pulse signals with defined initial delay, high time, low time, or period. In laboratories, it is commonly used to produce TTL triggers, synchronization pulses, gating signals, or timing control signals for coordinating lasers, cameras, detectors, and other instruments.",
  "tag_hints": [
    "NI-DAQ",
    "counter output",
    "timer pulse generation",
    "TTL trigger",
    "instrument synchronization",
    "timing control"
  ],
  "actions": [
    {
      "action_name": "auto-create_task",
      "description": "创建并配置计数器脉冲输出任务。",
      "description_en": "Create and configure the counter pulse output task."
    },
    {
      "action_name": "auto-start_task",
      "description": "启动计数器输出任务并开始输出脉冲。",
      "description_en": "Start the counter output task and begin pulse generation."
    },
    {
      "action_name": "auto-update_task",
      "description": "更新计数器输出任务的参数设置。",
      "description_en": "Update the parameter settings of the counter output task."
    },
    {
      "action_name": "auto-set_initial_delay_chan1",
      "description": "设置通道1脉冲输出的初始延时。",
      "description_en": "Set the initial delay of channel 1 pulse output."
    },
    {
      "action_name": "auto-set_initial_delay_chan2",
      "description": "设置通道2脉冲输出的初始延时。",
      "description_en": "Set the initial delay of channel 2 pulse output."
    },
    {
      "action_name": "auto-set_high_time1",
      "description": "设置通道1脉冲的高电平持续时间。",
      "description_en": "Set the high-level duration of the channel 1 pulse."
    },
    {
      "action_name": "auto-set_low_time1",
      "description": "设置通道1脉冲的低电平持续时间。",
      "description_en": "Set the low-level duration of the channel 1 pulse."
    },
    {
      "action_name": "auto-set_high_time2",
      "description": "设置通道2脉冲的高电平持续时间。",
      "description_en": "Set the high-level duration of the channel 2 pulse."
    },
    {
      "action_name": "auto-set_period2",
      "description": "设置通道2脉冲输出的周期。",
      "description_en": "Set the period of channel 2 pulse output."
    },
    {
      "action_name": "auto-set_trigger",
      "description": "设置触发模式或触发使能。",
      "description_en": "Set the trigger mode or trigger enable state."
    },
    {
      "action_name": "auto-set_trigger_source",
      "description": "设置触发源。",
      "description_en": "Set the trigger source."
    },
    {
      "action_name": "auto-set_trigger_edge",
      "description": "设置触发边沿。",
      "description_en": "Set the trigger edge."
    },
    {
      "action_name": "auto-stop_task",
      "description": "停止计数器输出任务。",
      "description_en": "Stop the counter output task."
    },
    {
      "action_name": "auto-close",
      "description": "关闭并释放计数器输出任务。",
      "description_en": "Close and release the counter output task."
    }
  ]
}

